import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";

const root = join(dirname(fileURLToPath(import.meta.url)), "..");

const env = process.env;

export const config = {
  port: Number(env.PORT ?? 3000),
  host: env.HOST ?? "0.0.0.0",
  /** Dataset generated by guessTheBlock/scripts/build-data.mjs (`npm run data`). */
  blocksPath:
    env.BLOCKS_PATH ??
    join(root, "..", "guessTheBlock", "public", "data", "blocks.json"),
  /** SQLite file for the link challenges; ":memory:" keeps nothing. */
  databasePath: env.DATABASE_PATH ?? join(root, "data", "guess-the-block.db"),
  /**
   * Origins allowed to call the API, comma separated, or "*".
   * The API uses no cookies (players send their id in a header), so "*" is safe.
   */
  allowedOrigins: (env.ALLOWED_ORIGINS ?? "*")
    .split(",")
    .map((o) => o.trim())
    .filter(Boolean),
  /** Use X-Forwarded-For for rate limits (set when behind a reverse proxy). */
  trustProxy: env.TRUST_PROXY === "1" || env.TRUST_PROXY === "true",
  /** How long a link challenge (and its leaderboard) is kept. */
  challengeTtlMs: Number(env.CHALLENGE_TTL_DAYS ?? 30) * 86_400_000,
  /** Duel rooms with nobody connected are dropped after this long. */
  roomIdleMs: Number(env.ROOM_IDLE_MINUTES ?? 120) * 60_000,
  maxRooms: Number(env.MAX_ROOMS ?? 5000),
  /** Seconds of "3, 2, 1" before a duel round starts. */
  countdownMs: Number(env.COUNTDOWN_SECONDS ?? 3) * 1000,
};
